# The SDK's own source root (the dir holding the ``workpeg`` package). SDK-
# shipped Component modules such as ``workpeg.ui.scaffold`` live here, not in
# the app tree, so import resolution falls back to this for ``workpeg.*``
# modules — letting their Components be parsed exactly like app-local ones.
_SDK_SRC_ROOT = str(Path(__file__).resolve().parents[3])


class UnsupportedSyntaxError(Exception):
    """Raised when source uses syntax outside the supported subset.

    ``file`` carries the offending file's path when known — set once at
    the file boundary (parse_file / _parse_class_from_file) so cross-file
    errors blame the page module, not main.py. It is included in str()
    so every consumer (CLI, terminal, dev overlay) shows it.
    """

    def __init__(self, message: str, file: "str | None" = None) -> None:
        super().__init__(message)
        self.file = file

    def __str__(self) -> str:
        base = super().__str__()
        if self.file:
            return f"{self.file}: {base}"
        return base


def _display_path(path: str) -> str:
    """Shorten *path* for error messages — relative to cwd when possible.

    A path OUTSIDE the project is reduced to its last two components rather
    than printed in full. On a laptop the difference is cosmetic; on a shared
    build server it is not, because a peg's own source decides which files get
    read (see ``_resolve_library_module``) and the resulting error text is
    returned to whoever submitted it. Printing the absolute path made that an
    oracle over the server's filesystem — "does /opt/secret/config.py exist,
    and what is on line 12" — answerable by writing an import.

    The tail is kept because the useful half of the message is which module
    failed, not where it was installed.
    """
    try:
        return str(Path(path).resolve().relative_to(Path.cwd()))
    except ValueError:
        parts = Path(path).parts
        return str(Path(*parts[-2:])) if len(parts) > 2 else Path(path).name


#: How deep an expression may nest before the compiler refuses it.
#:
#: CPython already stops the obvious shapes: the tokenizer caps bracket nesting
#: at 200 and indentation at 100. What it does NOT stop is a chain of unary or
#: binary operators — ``-`` repeated, ``not`` repeated, ``a.b.b.b…`` — which
#: parses happily to a depth of several thousand. ``ast.parse`` survives it;
#: every RECURSIVE CONSUMER of the tree does not, and this compiler is exactly
#: such a consumer.
#:
#: Measured: ``"x = " + "-"*3000 + "1"`` is 3 KB of source that parses fine and
#: then raises RecursionError inside the walk. On a laptop that is a confusing
#: traceback; on a build server it is a denial of service costing 3 KB to send.
#:
#: 200 matches the tokenizer's own bracket limit, so this refuses nothing a
#: developer can write with parentheses.
MAX_AST_DEPTH = 200


def assert_ast_depth(tree: "ast.AST", filename: str = "") -> int:
    """Refuse a tree deeper than ``MAX_AST_DEPTH``; return the depth.

    Iterative BY NECESSITY. The recursive version of this function is the very
    failure it exists to prevent — it would raise RecursionError on precisely
    the input it was added to reject, which reads as a crash rather than as a
    refusal and never reports the real reason.
    """
    deepest = 0
    stack = [(tree, 1)]
    while stack:
        node, depth = stack.pop()
        if depth > deepest:
            deepest = depth
            if deepest > MAX_AST_DEPTH:
                where = f"{_display_path(filename)}: " if filename else ""
                raise UnsupportedSyntaxError(
                    f"{where}expression nests more than {MAX_AST_DEPTH} levels "
                    f"deep. This is refused rather than compiled: a tree this "
                    f"deep exhausts the compiler's own stack."
                )
        for child in ast.iter_child_nodes(node):
            stack.append((child, depth + 1))
    return deepest


