def _is_str_const(node: "ast.AST | None") -> bool:
    """True when *node* is a string literal (an ``ast.Constant`` holding a str)
    — used by the icon-literal scan to pick out ``icon="…"`` values."""
    return isinstance(node, ast.Constant) and isinstance(node.value, str)


def _is_none_const(node: "ast.AST | None") -> bool:
    """True when *node* is a literal ``None`` — a keyword passed its class
    default explicitly, which must parse as though it were left out."""
    return isinstance(node, ast.Constant) and node.value is None


def _is_workpeg_host(url: str) -> bool:
    """True when *url* targets a Workpeg-owned host — ``workpeg`` as the
    REGISTRABLE label, the one right before the TLD (workpeg.com, *.workpeg.io,
    …), not merely somewhere in the name (so ``foo.workpeg.evil.com`` is NOT
    Workpeg). Relative URLs have no host and are never Workpeg. Mirrors
    ``Workpeg._isWorkpegHost`` in the runtime, including what a browser's URL
    parser does to a host: percent-decode it, and take a trailing dot as the
    same host, which DNS does and a comparison of labels does not."""
    try:
        host = urlparse(url).hostname
    except ValueError:
        return False
    if not host:
        return False
    labels = unquote(host).lower().rstrip(".").split(".")
    return len(labels) >= 2 and labels[-2] == "workpeg"


